const cart = {}; // { code: qty }
const money = v => v.toLocaleString('pt-BR', {style:'currency', currency:'BRL'});

const body = document.getElementById('productBody');
const emptyState = document.getElementById('emptyState');
const countPill = document.getElementById('countPill');

function renderList(filter){
  const f = (filter||'').trim().toLowerCase();
  const rows = [];
  let shown = 0;
  for(const p of PRODUCTS){
    if(f && !p.n.toLowerCase().includes(f) && String(p.c).indexOf(f) === -1) continue;
    shown++;
    const qty = cart[p.c] || 0;
    rows.push(`
      <tr data-code="${p.c}">
        <td class="code">#${p.c}</td>
        <td class="name">${p.n}</td>
        <td class="price">${money(p.p)}</td>
        <td class="qty">
          <div class="qty-box">
            <button class="dec" aria-label="Diminuir">−</button>
            <input type="number" min="0" value="${qty}" inputmode="numeric">
            <button class="inc" aria-label="Aumentar">+</button>
          </div>
        </td>
      </tr>
    `);
  }
  body.innerHTML = rows.join('');
  emptyState.style.display = shown ? 'none' : 'block';
  countPill.textContent = f ? `${shown} de ${PRODUCTS.length} produtos` : `${PRODUCTS.length} produtos`;
}

function setQty(code, qty){
  qty = Math.max(0, Math.min(9999, qty|0));
  if(qty === 0) delete cart[code];
  else cart[code] = qty;
  updateCartUI();
}

body.addEventListener('click', (e)=>{
  const tr = e.target.closest('tr');
  if(!tr) return;
  const code = Number(tr.dataset.code);
  if(e.target.classList.contains('inc')){
    const input = tr.querySelector('input');
    setQty(code, (Number(input.value)||0) + 1);
    input.value = cart[code] || 0;
  } else if(e.target.classList.contains('dec')){
    const input = tr.querySelector('input');
    setQty(code, (Number(input.value)||0) - 1);
    input.value = cart[code] || 0;
  }
});
body.addEventListener('change', (e)=>{
  if(e.target.tagName === 'INPUT'){
    const tr = e.target.closest('tr');
    const code = Number(tr.dataset.code);
    setQty(code, Number(e.target.value)||0);
  }
});

document.getElementById('searchInput').addEventListener('input', (e)=>{
  renderList(e.target.value);
});

function getPayment(){
  const el = document.querySelector('input[name="pay"]:checked');
  return el ? el.value : '';
}
document.querySelectorAll('input[name="pay"]').forEach(r=>r.addEventListener('change', updateCartUI));

function findProduct(code){ return PRODUCTS.find(p=>p.c===Number(code)); }

function updateCartUI(){
  const codes = Object.keys(cart);
  const badge = document.getElementById('cartBadge');
  const slipBody = document.getElementById('slipBody');
  const totalItems = document.getElementById('totalItems');
  const totalPrice = document.getElementById('totalPrice');
  const sendBtn = document.getElementById('sendBtn');

  let count = 0, sum = 0;
  codes.forEach(c=>{ count += cart[c]; });

  badge.textContent = count;

  if(codes.length === 0){
    slipBody.innerHTML = '<div class="slip-empty">Sua nota está vazia.<br>Adicione produtos no catálogo.</div>';
  } else {
    slipBody.innerHTML = codes.map(code=>{
      const p = findProduct(code);
      const line = p.p * cart[code];
      sum += line;
      return `
        <div class="slip-item" data-code="${code}">
          <span class="nm">${cart[code]}× ${p.n}</span>
          <span class="rhs">${money(line)}<button class="rm" aria-label="Remover">×</button></span>
        </div>
      `;
    }).join('');
  }

  totalItems.textContent = count;
  totalPrice.textContent = money(sum);
  sendBtn.disabled = codes.length === 0 || !getPayment();

  // sync qty inputs visible in table
  document.querySelectorAll('#productBody tr').forEach(tr=>{
    const code = tr.dataset.code;
    const input = tr.querySelector('input');
    if(input) input.value = cart[code] || 0;
  });
}

document.getElementById('slipBody').addEventListener('click', (e)=>{
  if(e.target.classList.contains('rm')){
    const item = e.target.closest('.slip-item');
    setQty(Number(item.dataset.code), 0);
  }
});

const slip = document.getElementById('slip');
const overlay = document.getElementById('overlay');
function openSlip(){ slip.classList.add('show'); overlay.classList.add('show'); }
function closeSlip(){ slip.classList.remove('show'); overlay.classList.remove('show'); }
document.getElementById('cartFab').addEventListener('click', openSlip);
document.getElementById('slipClose').addEventListener('click', closeSlip);
overlay.addEventListener('click', closeSlip);

document.getElementById('sendBtn').addEventListener('click', ()=>{
  const codes = Object.keys(cart);
  if(codes.length === 0 || !getPayment()) return;
  let sum = 0;
  const lines = codes.map(code=>{
    const p = findProduct(code);
    const line = p.p * cart[code];
    sum += line;
    return `• ${cart[code]}x ${p.n} — ${money(line)}`;
  });
  let msg = `Olá! Gostaria de fazer o seguinte pedido:\n\n`;
  msg += lines.join('\n');
  msg += `\n\nTotal: ${money(sum)}`;
  msg += `\nPagamento: ${getPayment()}`;
  const url = `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(msg)}`;
  window.open(url, '_blank');
});

// persist cart locally so a reload doesn't lose it
try{
  const saved = localStorage.getItem('confespan_cart');
  if(saved) Object.assign(cart, JSON.parse(saved));
}catch(e){}
function persist(){
  try{ localStorage.setItem('confespan_cart', JSON.stringify(cart)); }catch(e){}
}
const _setQty = setQty;
setQty = function(code, qty){ _setQty(code, qty); persist(); };

renderList('');
updateCartUI();